<script setup lang="ts">
import { computed, shallowRef, watch } from 'vue'
import type { WorkbenchRun } from '../../types/workbench'
import { downloadArtifact } from '../../api/workbench'
import RunTimeline from './RunTimeline.vue'
import EvaluationResults from './EvaluationResults.vue'
import ImageEvidencePanel from './ImageEvidencePanel.vue'
import AgentDispatchCard from '../agent/AgentDispatchCard.vue'
import AgentContextMap from '../agent/AgentContextMap.vue'
import AgentVisionResult from '../agent/AgentVisionResult.vue'
import type { AgentMapTarget } from '../../types/agent'
const props = defineProps<{ run: WorkbenchRun; disabled: boolean; canOperate: boolean }>()
const emit = defineEmits<{ action: [name: string, input: Record<string, unknown>]; ask: [question: string] }>()
const consent = shallowRef(false), tasks = shallowRef(''), plan = shallowRef(''), target = shallowRef<AgentMapTarget>()
watch(() => props.run.id, () => { consent.value = false; tasks.value = ''; plan.value = ''; target.value = undefined })
const resumable = computed(() => ['workflow','evaluation'].includes(props.run.kind) && ['interrupted', 'failed', 'cancelled'].includes(props.run.status) && props.run.checkpoint.step !== 'preview')
const live = computed(() => props.run.input.mode === 'live' || props.run.input.evaluation_mode === 'agent')
const taskIds = computed(() => tasks.value.split(/[,，\s]+/).filter(Boolean))
function action(name: string, extra: Record<string, unknown> = {}) { emit('action', name, { revision: props.run.revision, external_allowed: consent.value, ...extra }) }
</script>
<template><article class="inspector"><h2>{{ run.id }} · {{ run.status }}</h2><p>{{ run.checkpoint.message }}</p><p>当前步骤 {{ run.checkpoint.step ?? '未开始' }} · 版本 {{ run.revision }} · {{ run.input.mode === 'demo' ? '独立合成样例，无模型/业务请求' : '实际运行记录' }}</p><label v-if="live && resumable"><input v-model="consent" type="checkbox">确认恢复时可重新发送未完成的只读模型请求及所选证据</label><div class="actions"><button :disabled="disabled || !resumable || (live && (!consent || !canOperate))" @click="action('resume')">从成功检查点恢复</button><button :disabled="disabled || !['running','interrupted','failed','awaiting_review'].includes(run.status) || run.checkpoint.step === 'preview'" @click="action('cancel')">取消分析</button><button @click="downloadArtifact(run, `${run.id}.json`)">导出运行与轨迹JSON</button></div><section v-if="run.checkpoint.answer"><h3>建议正文</h3><pre>{{ run.checkpoint.answer.text }}</pre><details v-for="source in run.checkpoint.answer.sources" :key="source.citation_id"><summary>[{{ source.citation_id }}] {{ source.source }} · {{ source.section }}</summary><p>{{ source.text }}</p><small>版本 {{ source.version }}</small></details></section><ImageEvidencePanel v-if="run.input.mode === 'live' && run.input.source_kind === 'analysis' && run.input.source_id" :analysis-id="run.input.source_id" @ask="emit('ask', $event)" /><ImageEvidencePanel v-if="run.input.mode === 'live' && run.input.compare_id" :analysis-id="run.input.compare_id" @ask="emit('ask', `请对比所选两份分析，${$event}`)" /><details v-if="run.checkpoint.evidence"><summary>服务端证据快照（历史快照，执行前需重查）</summary><pre>{{ JSON.stringify(run.checkpoint.evidence, null, 2) }}</pre></details><details><summary>执行版本与检索记录</summary><pre>{{ JSON.stringify({ versions: run.checkpoint.versions, retrieval: run.checkpoint.retrieval }, null, 2) }}</pre></details><EvaluationResults v-if="run.kind === 'evaluation'" :rows="run.checkpoint.rows ?? []" /><AgentVisionResult v-if="run.kind==='vision_chat' && run.checkpoint.response" :result="run.checkpoint.response"/><RunTimeline :run="run" /><section v-if="run.status === 'awaiting_review' && run.input.mode === 'live'"><h3>明确选择任务，生成Java方案</h3><p>填写待分配任务编号，以逗号分隔，最多20项。服务端重新读取任务并校验；这里只生成预览，不自动确认分配。</p><input v-model="tasks" aria-label="待生成方案任务编号" maxlength="850"><button :disabled="disabled || !canOperate || !taskIds.length || taskIds.length > 20" @click="action('preview', { task_ids: taskIds })">为所选任务生成预览</button></section><section v-if="run.status === 'needs_reconcile' || (run.status === 'interrupted' && run.checkpoint.step === 'preview')"><p>预览响应不确定。先到Agent指挥的算法调度历史核对，不要重复生成。</p><input v-model="plan" aria-label="核对后的Java方案编号" placeholder="DP-…"><button :disabled="disabled || !plan" @click="action('reconcile', { plan_id: plan })">核对并关联方案</button></section><AgentDispatchCard v-if="run.checkpoint.plan_id" :plan-id="run.checkpoint.plan_id" @locate="target = $event" /><button v-if="run.checkpoint.plan_id" :disabled="disabled" @click="action('reconcile')">从Java同步确认结果</button><el-dialog :model-value="!!target" title="方案地图 · 仿真" width="95%" destroy-on-close @close="target = undefined"><AgentContextMap v-if="target" :target="target" /></el-dialog></article></template>
<style scoped>.inspector{padding:18px;background:#0c2233;border:1px solid #31546b;min-width:0}.inspector pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:500px;overflow:auto;color:#d3e8f5;font:13px/1.8 sans-serif}.inspector p{color:#9ebfd2;line-height:1.8}.inspector small{overflow-wrap:anywhere}.actions{display:flex;gap:10px;flex-wrap:wrap}.inspector input:not([type=checkbox]){padding:8px;background:#102a3d;color:#fff;border:1px solid #36536b;min-width:260px}.inspector details{padding:10px 0;border-bottom:1px solid #284254}.inspector h2{overflow-wrap:anywhere}</style>
